code_string = """from qiskit import transpile
from scipy.optimize import minimize

def run_and_analyze(circuit, aer_sim, graph):
    transpiled_circuit = transpile(circuit, aer_sim)
    params = list(transpiled_circuit.parameters)
    initial_value = 0.0
    initial_params = [initial_value] * circuit.num_parameters

    def objective(values):
        bind = {}
        for i in range(len(params)):
            bind[params[i]] = [float(values[i])]
        job = aer_sim.run(transpiled_circuit, shots=256, parameter_binds=[bind])
        counts = job.result().get_counts(0)
        return -float(compute_expectation(counts, graph))

    if circuit.num_parameters > 0:
        result = minimize(objective, initial_params, method='COBYLA', options={'maxiter': 8})
        final_params = list(result.x)
    else:
        final_params = initial_params

    final_bind = {}
    for i in range(len(params)):
        final_bind[params[i]] = [float(final_params[i])]
    final_job = aer_sim.run(transpiled_circuit, shots=2048, parameter_binds=[final_bind])
    final_counts = final_job.result().get_counts(0)
    top_two = sorted(final_counts, key=final_counts.get, reverse=True)[:2]
    return top_two
"""
